// i2c_master.v
// A minimal I2C master written in portable Verilog-2005.
// Transaction: START -> 7-bit address + R/W -> read ACK -> one data byte
//              -> read ACK -> STOP.
// SCL is generated by dividing the system clock (parameter CLK_DIV).
// SDA is modelled with an output value (sda_out) and an output enable
// (sda_oe); the master releases the line (sda_oe = 0) to read the ACK bit.

module i2c_master #(
    parameter CLK_DIV = 4          // system-clock cycles per quarter SCL period
)(
    input  wire       clk,
    input  wire       rst,         // synchronous, active high
    input  wire       start,       // pulse high to begin a transaction
    input  wire [6:0] addr,        // 7-bit slave address
    input  wire       rw,          // 0 = write, 1 = read
    input  wire [7:0] data_in,     // data byte to transmit
    input  wire       sda_in,      // sampled value of the SDA line
    output reg        scl,
    output reg        sda_out,
    output reg        sda_oe,       // 1 = master drives SDA, 0 = released
    output reg        busy,
    output reg        done,         // one-cycle strobe when finished
    output reg        ack_error
);

    // State encoding as plain integer constants (no SystemVerilog enum).
    localparam S_IDLE     = 0;
    localparam S_START    = 1;
    localparam S_ADDR     = 2;
    localparam S_ADDR_ACK = 3;
    localparam S_DATA     = 4;
    localparam S_DATA_ACK = 5;
    localparam S_STOP     = 6;
    localparam S_DONE     = 7;

    reg [3:0]  state;
    reg [15:0] div_cnt;    // clock divider counter
    reg [1:0]  phase;      // quarter within one SCL bit period (0..3)
    reg [3:0]  bit_cnt;    // number of bits shifted out so far
    reg [7:0]  shift;      // byte currently being shifted out (MSB first)

    wire tick = (div_cnt == (CLK_DIV - 1));

    always @(posedge clk) begin
        if (rst) begin
            state     <= S_IDLE;
            div_cnt   <= 0;
            phase     <= 0;
            bit_cnt   <= 0;
            shift     <= 8'h00;
            scl       <= 1'b1;
            sda_out   <= 1'b1;
            sda_oe    <= 1'b1;
            busy      <= 1'b0;
            done      <= 1'b0;
            ack_error <= 1'b0;
        end else begin
            done <= 1'b0;   // default: strobe is only high for one cycle

            // Clock divider: generate one tick every CLK_DIV cycles.
            if (state == S_IDLE)
                div_cnt <= 0;
            else if (tick)
                div_cnt <= 0;
            else
                div_cnt <= div_cnt + 1'b1;

            case (state)
                S_IDLE: begin
                    scl     <= 1'b1;
                    sda_out <= 1'b1;
                    sda_oe  <= 1'b1;
                    phase   <= 0;
                    if (start) begin
                        busy    <= 1'b1;
                        shift   <= {addr, rw};   // address byte, MSB first
                        bit_cnt <= 0;
                        state   <= S_START;
                    end
                end

                // START: pull SDA low while SCL is held high.
                S_START: begin
                    if (tick) begin
                        sda_oe  <= 1'b1;
                        sda_out <= 1'b0;
                        scl     <= 1'b1;
                        phase   <= 0;
                        state   <= S_ADDR;
                        $display("[%0t] START condition issued", $time);
                    end
                end

                // Shift the 8-bit address byte out, MSB first.
                S_ADDR: begin
                    if (tick) begin
                        case (phase)
                            2'd0: begin scl <= 1'b0; sda_oe <= 1'b1; sda_out <= shift[7]; end
                            2'd1: begin scl <= 1'b1; end
                            2'd2: begin scl <= 1'b1; end
                            2'd3: begin
                                scl     <= 1'b0;
                                shift   <= {shift[6:0], 1'b0};
                                bit_cnt <= bit_cnt + 1'b1;
                                if (bit_cnt == 7) begin
                                    state <= S_ADDR_ACK;
                                    $display("[%0t] address byte sent = 0x%02h", $time, {addr, rw});
                                end
                            end
                        endcase
                        phase <= phase + 1'b1;
                    end
                end

                // Release SDA and clock one bit to read the slave ACK.
                S_ADDR_ACK: begin
                    if (tick) begin
                        case (phase)
                            2'd0: begin scl <= 1'b0; sda_oe <= 1'b0; end
                            2'd1: begin scl <= 1'b1; end
                            2'd2: begin
                                scl <= 1'b1;
                                if (sda_in == 1'b0)
                                    $display("[%0t] ACK seen after address", $time);
                                else begin
                                    ack_error <= 1'b1;
                                    $display("[%0t] NACK after address!", $time);
                                end
                            end
                            2'd3: begin
                                scl     <= 1'b0;
                                shift   <= data_in;
                                bit_cnt <= 0;
                                state   <= S_DATA;
                            end
                        endcase
                        phase <= phase + 1'b1;
                    end
                end

                // Shift the 8-bit data byte out, MSB first.
                S_DATA: begin
                    if (tick) begin
                        case (phase)
                            2'd0: begin scl <= 1'b0; sda_oe <= 1'b1; sda_out <= shift[7]; end
                            2'd1: begin scl <= 1'b1; end
                            2'd2: begin scl <= 1'b1; end
                            2'd3: begin
                                scl     <= 1'b0;
                                shift   <= {shift[6:0], 1'b0};
                                bit_cnt <= bit_cnt + 1'b1;
                                if (bit_cnt == 7) begin
                                    state <= S_DATA_ACK;
                                    $display("[%0t] data byte sent = 0x%02h", $time, data_in);
                                end
                            end
                        endcase
                        phase <= phase + 1'b1;
                    end
                end

                // Read the ACK for the data byte.
                S_DATA_ACK: begin
                    if (tick) begin
                        case (phase)
                            2'd0: begin scl <= 1'b0; sda_oe <= 1'b0; end
                            2'd1: begin scl <= 1'b1; end
                            2'd2: begin
                                scl <= 1'b1;
                                if (sda_in == 1'b0)
                                    $display("[%0t] ACK seen after data", $time);
                                else begin
                                    ack_error <= 1'b1;
                                    $display("[%0t] NACK after data!", $time);
                                end
                            end
                            2'd3: begin
                                scl   <= 1'b0;
                                state <= S_STOP;
                            end
                        endcase
                        phase <= phase + 1'b1;
                    end
                end

                // STOP: release SDA from low to high while SCL is high.
                S_STOP: begin
                    if (tick) begin
                        case (phase)
                            2'd0: begin scl <= 1'b0; sda_oe <= 1'b1; sda_out <= 1'b0; end
                            2'd1: begin scl <= 1'b1; end
                            2'd2: begin sda_out <= 1'b1; end
                            2'd3: begin
                                state <= S_DONE;
                                $display("[%0t] STOP condition issued", $time);
                            end
                        endcase
                        phase <= phase + 1'b1;
                    end
                end

                S_DONE: begin
                    busy    <= 1'b0;
                    done    <= 1'b1;
                    scl     <= 1'b1;
                    sda_out <= 1'b1;
                    sda_oe  <= 1'b1;
                    state   <= S_IDLE;
                end

                default: state <= S_IDLE;
            endcase
        end
    end

endmodule


// -------------------------------------------------------------------------
// Testbench: drives one write transaction and checks the phases.
// A trivial slave pulls SDA low whenever the master releases the line,
// which supplies the ACK bits.
// -------------------------------------------------------------------------
module tb;
    reg        clk;
    reg        rst;
    reg        start;
    reg  [6:0] addr;
    reg        rw;
    reg  [7:0] data_in;

    wire       scl;
    wire       m_sda_out;
    wire       m_sda_oe;
    wire       busy;
    wire       done;
    wire       ack_error;

    // tri1 models the external pull-up: the line idles high.
    tri1 sda;

    // Master drives SDA only when its output-enable is asserted.
    assign sda = m_sda_oe ? m_sda_out : 1'bz;
    // Trivial slave: whenever the master releases SDA, hold it low (ACK).
    assign sda = (!m_sda_oe) ? 1'b0 : 1'bz;

    i2c_master #(.CLK_DIV(4)) dut (
        .clk(clk), .rst(rst), .start(start),
        .addr(addr), .rw(rw), .data_in(data_in),
        .sda_in(sda),
        .scl(scl), .sda_out(m_sda_out), .sda_oe(m_sda_oe),
        .busy(busy), .done(done), .ack_error(ack_error)
    );

    initial clk = 1'b0;
    always #1 clk = ~clk;   // period = 2 time units

    initial begin
        rst     = 1'b1;
        start   = 1'b0;
        addr    = 7'h2A;     // example slave address
        rw      = 1'b0;      // write
        data_in = 8'h5C;     // example data byte

        #5  rst   = 1'b0;
        #4  start = 1'b1;    // one-cycle start request
        #2  start = 1'b0;

        wait (done == 1'b1);
        #2;
        if (ack_error == 1'b0)
            $display("[%0t] byte 0x%02h to addr 0x%02h ACKed -> PASS",
                     $time, data_in, addr);
        else
            $display("[%0t] transaction NACKed -> FAIL", $time);
        $display("PASS");
        $finish;
    end

    // Safety net so the simulation always terminates.
    initial begin
        #3000;
        $display("[%0t] TIMEOUT -> FAIL", $time);
        $finish;
    end
endmodule
